message.content:
{
  "title": "The Gilded Cage Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party reaches the ruined city gates.",
      "visual_description": "Crumbling stone gates flanked by faded royal banners, the city shrouded in mist beyond.",
      "characters": ["Aric", "Mira", "Torben"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople whisper warnings at a market square.",
      "visual_description": "A desolate square with overturned carts; huddled figures in ragged clothes point toward a distant tower.",
      "characters": ["Aric", "Mira", "Torben", "Elder Lira"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrols march through the outer district.",
      "visual_description": "Black-armored soldiers with glowing red eyes march in unison, torches casting long shadows.",
      "characters": ["Aric", "Mira", "Torben", "Patrol Captain"]
    },
    {
      "scene_number": 4,
      "caption": "The party hides in an abandoned inn and plans their route.",
      "visual_description": "Dusty common room with a shattered chandelier; a map spread on a wooden table candlelit.",
      "characters": ["Aric", "Mira", "Torben"]
    },
    {
      "scene_number": 5,
      "caption": "They encounter a cursed tower guarded by spectral knights.",
      "visual_description": "A twisted spire wrapped in thorny vines, ghostly knights in rusted armor blocking the entrance.",
      "characters": ["Aric", "Mira", "Torben", "Spectral Knights"]
    },
    {
      "scene_number": 6,
      "caption": "Mira disables a magic door with a stolen sigil.",
      "visual_description": "Ornate stone door glowing with runes; Mira presses a cracked sigil into a recess, the glow fading.",
      "characters": ["Aric", "Mira", "Torben"]
    },
    {
      "scene_number": 7,
      "caption": "They glimpse a dragon circling the palace spire.",
      "visual_description": "A crimson dragon with tattered wings glides above the ruined palace, lightning flickering behind it.",
      "characters": ["Aric", "Mira", "Torben"]
    },
    {
      "scene_number": 8,
      "caption": "Aric confronts rumors of the dragon's lair in the throne room.",
      "visual_description": "Broken stained-glass window showing a dragon; Aric listens to echoing whispers from the hall.",
      "characters": ["Aric", "Mira", "Torben"]
    },
    {
      "scene_number": 9,
      "caption": "They find the rescue target chained in the palace dungeon.",
      "visual_description": "Damp cell with iron bars; a figure in chains, cloak torn, eyes defiant but tired.",
      "characters": ["Aric", "Mira", "Torben", "Princess Elara"]
    },
    {
      "scene_number": 10,
      "caption": "Princess Elara reveals the curse that binds the city.",
      "visual_description": "Elara points to a glowing symbol on her palm; the room trembles as she speaks.",
      "characters": ["Aric", "Mira", "Torben", "Princess Elara"]
    },
    {
      "scene_number": 11,
      "caption": "They fight through a patrol in the palace courtyard.",
      "visual_description": "Overgrown courtyard with a dry fountain; armored patrols converge, weapons drawn.",
      "characters": ["Aric", "Mira", "Torben", "Princess Elara", "Patrol Captain"]
    },
    {
      "scene_number": 12,
      "caption": "Torben uses a distraction to open a secret passage.",
      "visual_description": "Torben slams a lever behind a tapestry; a grinding sound opens a stone door in the wall.",
      "characters": ["Aric", "Mira", "Torben", "Princess Elara"]
    },
    {
      "scene_number": 13,
      "caption": "They navigate a hall of mirrors that shows their fears.",
      "visual_description": "Endless reflections twist into monstrous shapes; each character sees a personal nightmare.",
      "characters": ["Aric", "Mira", "Torben", "Princess Elara"]
    },
    {
      "scene_number": 14,
      "caption": "The dragon awakens and blocks their path to the bridge.",
      "visual_description": "The dragon lands on a battlement, wings spread, eyes burning like coals.",
      "characters": ["Aric", "Mira", "Torben", "Princess Elara", "The Dragon"]
    },
    {
      "scene_number": 15,
      "caption": "Aric negotiates a truce with the dragon using Elara's knowledge.",
      "visual_description": "Aric holds up the glowing symbol; the dragon snorts smoke, then lowers its head.",
      "characters": ["Aric", "Mira", "Torben", "Princess Elara", "The Dragon"]
    },
    {
      "scene_number": 16,
      "caption": "They race across the ancient bridge as it crumbles.",
      "visual_description": "Stone bridge over a chasm, cracks spreading as arrows fly from the city walls.",
      "characters": ["Aric", "Mira", "Torben", "Princess Elara"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge collapses behind them, cutting off pursuit.",
      "visual_description": "The last section of bridge falls into the mist below; the city looms darkly in the distance.",
      "characters": ["Aric", "Mira", "Torben", "Princess Elara"]
    },
    {
      "scene_number": 18,
      "caption": "The party watches the sunrise from a safe hill.",
      "visual_description": "Golden light breaks over the horizon; the ruined city lies silent behind them.",
      "characters": ["Aric", "Mira", "Torben", "Princess Elara"]
    }
  ]
}

